def ikili_arama(dizi, hedef):
    sol, sag = 0, len(dizi) - 1
    while sol <= sag:
        orta = (sol + sag) // 2
        if dizi[orta] == hedef:
            return orta
        if dizi[orta] < hedef:
            sol = orta + 1
        else:
            sag = orta - 1
    return -1

def kabarcik_sirala(dizi):
    dizi = list(dizi)
    n = len(dizi)
    for i in range(n):
        degisti = False
        for j in range(n - 1 - i):
            if dizi[j] > dizi[j + 1]:
                dizi[j], dizi[j + 1] = dizi[j + 1], dizi[j]
                degisti = True
        if not degisti:
            break
    return dizi

def birlestir_sirala(dizi):
    if len(dizi) <= 1:
        return list(dizi)
    orta = len(dizi) // 2
    sol = birlestir_sirala(dizi[:orta])
    sag = birlestir_sirala(dizi[orta:])
    sonuc, i, j = [], 0, 0
    while i < len(sol) and j < len(sag):
        if sol[i] <= sag[j]:
            sonuc.append(sol[i]); i += 1
        else:
            sonuc.append(sag[j]); j += 1
    return sonuc + sol[i:] + sag[j:]

