def sezar_sifrele(metin, kaydirma):
    sonuc = []
    for c in metin:
        if 'a' <= c <= 'z':
            sonuc.append(chr((ord(c) - 97 + kaydirma) % 26 + 97))
        elif 'A' <= c <= 'Z':
